+        let row = selection.cursor.row.min(max_row);
+        let column = selection
+            .cursor
+            .column
+            .min(usize::from(width.saturating_sub(1)));
+        Some((
+            origin_y.saturating_add(row.min(usize::from(height.saturating_sub(1))) as u16),
+            origin_x.saturating_add(column as u16),
+        ))
+    }
