+fn apply_delta(value: usize, delta: isize) -> usize {
+    if delta < 0 {
+        value.saturating_sub((-delta) as usize)
+    } else {
+        value.saturating_add(delta as usize)
+    }
+}
+
+fn text_lines(content: &str) -> Vec<String> {
+    if content.is_empty() {
+        Vec::new()
+    } else {
+        content.lines().map(str::to_string).collect()
+    }
+}
+
+fn selection_text(
+    lines: &[String],
+    selection: &VisualSelection,
+    kind: VisualKind,
+) -> String {
+    selection_ranges(lines, selection, kind)
+        .into_iter()
+        .filter_map(|(row, start, end)| lines.get(row).map(|line| slice_chars(line, start, end)))
+        .collect::<Vec<_>>()
+        .join("\n")
+}
+
+fn selection_ranges(
+    lines: &[String],
+    selection: &VisualSelection,
+    kind: VisualKind,
+) -> Vec<(usize, usize, usize)> {
+    if lines.is_empty() {
+        return Vec::new();
+    }
+    let start_row = selection.anchor.row.min(selection.cursor.row);
+    let end_row = selection
+        .anchor
+        .row
+        .max(selection.cursor.row)
+        .min(lines.len().saturating_sub(1));
+    let start_column = selection.anchor.column.min(selection.cursor.column);
+    let end_column = selection.anchor.column.max(selection.cursor.column);
+
+    match kind {
+        VisualKind::Line => (start_row..=end_row)
+            .map(|row| (row, 0, line_char_count(lines, row).max(1)))
+            .collect(),
+        VisualKind::Block => (start_row..=end_row)
+            .map(|row| (row, start_column, end_column.saturating_add(1)))
+            .collect(),
+        VisualKind::Character if selection.anchor.row == selection.cursor.row => {
+            vec![(
+                start_row,
+                start_column,
+                end_column.saturating_add(1),
+            )]
+        }
+        VisualKind::Character => (start_row..=end_row)
+            .map(|row| {
+                if row == selection.anchor.row {
+                    (row, selection.anchor.column, line_char_count(lines, row).max(1))
+                } else if row == selection.cursor.row {
+                    (row, 0, selection.cursor.column.saturating_add(1))
+                } else {
+                    (row, 0, line_char_count(lines, row).max(1))
+                }
+            })
+            .collect(),
+    }
+}
+
+fn line_char_count(lines: &[String], row: usize) -> usize {
+    lines
+        .get(row)
+        .map(|line| line.chars().count())
+        .unwrap_or_default()
+}
+
+fn slice_chars(line: &str, start: usize, end: usize) -> String {
+    line.chars()
+        .skip(start)
+        .take(end.saturating_sub(start))
+        .collect()
+}
+
+fn osc52_copy_sequence(text: &str) -> String {
+    format!("\u{1b}]52;c;{}\u{7}", base64_encode(text.as_bytes()))
+}
+
+fn base64_encode(bytes: &[u8]) -> String {
+    const ALPHABET: &[u8; 64] =
+        b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
+    let mut encoded = String::new();
+    for chunk in bytes.chunks(3) {
+        let b0 = chunk[0];
+        let b1 = *chunk.get(1).unwrap_or(&0);
+        let b2 = *chunk.get(2).unwrap_or(&0);
+        let n = (u32::from(b0) << 16) | (u32::from(b1) << 8) | u32::from(b2);
+        encoded.push(ALPHABET[((n >> 18) & 0x3f) as usize] as char);
+        encoded.push(ALPHABET[((n >> 12) & 0x3f) as usize] as char);
+        if chunk.len() > 1 {
+            encoded.push(ALPHABET[((n >> 6) & 0x3f) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+        if chunk.len() > 2 {
+            encoded.push(ALPHABET[(n & 0x3f) as usize] as char);
+        } else {
+            encoded.push('=');
+        }
+    }
+    encoded
+}
